import {createCanvas} from './vendor/ecs-canvas/canvas.js';
const $=id=>document.getElementById(id),id=location.pathname.split('/').filter(Boolean)[1],base='/api/map/'+encodeURIComponent(id),embed=new URLSearchParams(location.search).has('embed');
if(embed)document.body.classList.add('embed');
let graph,canvas,focus=null,selected='',generation=0,detailSequence=0,searchSequence=0,librariesInitialized=false,host=false,requestSequence=0,activeRequest=null;
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]);
const api=async(path)=>{const r=await fetch(base+path);if(!r.ok)throw Error((await r.json()).error||'Map request failed');return r;};
const options=()=>({libraries:$('map-libraries').checked?'1':'0',candidates:$('map-candidates').checked?'1':'0'});
function message(e){$('map-message').textContent=e?.message||String(e||'');}
function list(rows){$('map-list').replaceChildren();for(const n of rows){const b=document.createElement('button');b.type='button';b.dataset.node=n.id;b.setAttribute('aria-current',String(selected===n.id));b.innerHTML=`${esc(n.label)}<small>${esc(n.kind==='prefix'?'prefix container':n.kind)} · ${esc(n.detail&&n.kind==='prefix'?n.detail:n.scope||'')}</small>`;b.onclick=()=>inspect(n.id).catch(message);$('map-list').append(b);}if(!rows.length)$('map-list').innerHTML='<p class="empty">No matching entities. Refresh sources or broaden the search.</p>';}
function prepare(tool,args,schema){$('map-call-tool').textContent=tool;$('map-call-tool').dataset.tool=tool;$('map-call-args').value=JSON.stringify(args,null,2);$('map-call-schema').textContent=JSON.stringify(schema||{},null,2);$('map-call').hidden=false;$('map-call-run').disabled=!host;}
function runTool(tool,args){if(!host)throw Error('Open this map in Admin to run tools.');if(activeRequest)throw Error('Wait for the current tool result before running another.');const request=String(++requestSequence);activeRequest=request;$('map-call-run').disabled=true;$('map-call-status').textContent='Running '+tool+'…';parent.postMessage({type:'dt:map-run',map:id,node:selected,tool,arguments:args,request},'*');}
async function inspect(node){
 if(activeRequest)throw Error('Wait for the current inspection before selecting another node.');
 const sequence=++detailSequence;selected=node;for(const b of $('map-list').querySelectorAll('button'))b.setAttribute('aria-current',String(b.dataset.node===node));
 const r=await(await api('/node?id='+encodeURIComponent(node))).json();if(sequence!==detailSequence)return;
 const n=r.node,panel=$('map-detail');panel.innerHTML=`<h2>${esc(n.label)}</h2><span class="chip">${esc(n.kind)}</span><p class="muted">${esc(n.id)}</p><p>${esc(n.detail)}</p>${n.repo?`<p>Repository: ${esc(n.repo)}<br>${esc(n.revision?.slice(0,12))}</p>`:''}<p>Source: ${esc(n.source||'derived')}</p><button id="map-neighbors">${n.kind==='prefix'?'Expand prefix':'Explore connections'}</button><h3>Inspect with tools</h3><div id="map-actions"></div><section id="map-call" hidden><strong id="map-call-tool"></strong><label for="map-call-args">Editable arguments</label><textarea id="map-call-args" rows="8" spellcheck="false"></textarea><details><summary>Argument schema</summary><pre id="map-call-schema"></pre></details><button id="map-call-run" ${host?'':'disabled'}>Run tool</button><p id="map-call-status" role="status">${host?'Review arguments, then run.':'Run tools from Admin. This public embed is read-only.'}</p></section><section id="map-tool-output" hidden><h3>Tool result</h3><p id="map-tool-status" role="status"></p><iframe id="map-tool-view" title="Inspection result" sandbox="allow-scripts allow-popups allow-downloads" hidden></iframe><details id="map-tool-raw"><summary>Result data</summary><pre id="map-tool-json"></pre></details><div id="map-edit-adjustments"></div></section><details open><summary>Connection evidence</summary><div id="map-evidence-detail">Loading sources…</div></details><details id="map-correct"><summary>Adjust identities or connections</summary><p>Keep deployments, UI repositories and backend services separate. Supply a user statement, file/property or observed request as evidence. Corrections survive refreshes.</p><div id="map-questions"></div><button id="map-correct-edit">Prepare correction</button><button id="map-correct-list">Review saved corrections</button></details>`;
 const response=await(await api('/neighbors?'+new URLSearchParams({id:node,...options()}))).json();if(sequence!==detailSequence)return;
 const rows=response.text?response.text.split('\n'):[];$('map-evidence-detail').replaceChildren();for(const line of rows){const [from,kind,to,certainty,where,layer,evidence]=line.split('\t'),d=document.createElement('details');d.innerHTML=`<summary>${esc(kind)} · ${esc(certainty)}</summary><p>${esc(from)} → ${esc(to)}</p><p>${esc(where)}</p><p>${esc(evidence)}</p>${layer?'<p>Layer: '+esc(layer)+'</p>':''}`;$('map-evidence-detail').append(d);}if(!rows.length)$('map-evidence-detail').textContent='No evidenced connections in this filter. Candidates are hidden unless requested.';
 for(const link of r.links||[]){const a=document.createElement('a'),url=new URL(link.url,location.href);a.href=url.pathname+url.search;a.textContent=link.label;a.target='_blank';a.rel='noopener';panel.append(a);}
 $('map-neighbors').onclick=()=>{focus=node;load().catch(message);};
 for(const action of r.actions){const b=document.createElement('button');b.type='button';b.className='map-action';b.disabled=!action.valid;b.innerHTML=`${esc(action.tool)}<small>${esc(action.why)}</small>`;b.onclick=()=>{prepare(action.tool,action.arguments,action.schema);parent.postMessage({type:'dt:map-action',map:id,node,tool:action.tool},'*');};$('map-actions').append(b);}
 $('map-call-run').onclick=()=>{try{const args=JSON.parse($('map-call-args').value);if(!args||Array.isArray(args)||typeof args!=='object')throw Error('Arguments must be a JSON object');runTool($('map-call-tool').dataset.tool,args);}catch(e){$('map-call-status').textContent=e.message;}};
 $('map-questions').textContent=(r.questions||[]).join(' ');
 $('map-correct-edit').onclick=()=>prepare('map_adjust',{id:'binding-'+n.label.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,70),evidence:'',nodes:n.kind==='ui'?[{id:'uirepo:PROJECT/ui-repo',kind:'ui-repository',label:'UI repository',repo:'PROJECT/ui-repo'}]:[],edges:[{from:n.id,to:n.kind==='ui'?'uirepo:PROJECT/ui-repo':'svc:backend-service',relation:n.kind==='ui'?'deployment-of':'calls-http'}]});
 $('map-correct-list').onclick=()=>{prepare('map_adjustments',{});};
 parent.postMessage({type:'dt:map-selected',map:id,node},'*');
}
function documentFor(g){
 const all=Array.from({length:g.count},(_,i)=>g.node(i)),edges=Array.from({length:g.edgeCount},(_,i)=>g.edge(i)),members=new Map();
 for(const e of edges)if(e.kind==='contains'&&all[e.from].kind==='prefix'){const key=all[e.from].id;if(!members.has(key))members.set(key,[]);members.get(key).push(all[e.to].id);}
 const inventory=!focus;const groups=all.filter(n=>n.kind==='prefix'),ordinary=all.filter(n=>n.kind!=='prefix'),nodes=[],containers=[];let y=0;
 for(const group of groups){const children=ordinary.filter(n=>(members.get(group.id)||[]).includes(n.id)),cols=Math.min(children.length||1,$('map-canvas').clientWidth<700?1:2),w=cols*240+36,h=Math.max(110,Math.ceil(children.length/cols)*105+65);containers.push({id:group.id,Label:{text:group.label+' · '+(group.detail||'service prefix')+(inventory?' · expand':'')},Position:{x:w/2,y:y+h/2},Size:{w,h},ContainerType:'group',AutoFit:false,Color:'gray',Children:children.map(n=>({kind:'node',id:n.id}))});children.forEach((n,i)=>nodes.push(draft(n,24+(i%cols)*240,y+50+Math.floor(i/cols)*105)));y+=h+38;}
 if(inventory){const columns=$('map-canvas').clientWidth>650?2:1;containers.forEach((c,i)=>{c.Position={x:(i%columns)*315+145,y:Math.floor(i/columns)*150+56};c.Size={w:290,h:112};});}
 let extra=0;for(const n of ordinary)if(!nodes.some(row=>row.id===n.id)){const x=inventory?0:(groups.length?Math.max(...containers.map(c=>c.Size.w))+60:0),baseline=inventory?Math.ceil(containers.length/($('map-canvas').clientWidth>650?2:1))*150+20:0;nodes.push(draft(n,x,baseline+extra*110));extra++;}
 const rendered=edges.filter(e=>e.kind!=='contains'&&all[e.from].kind!=='prefix'&&all[e.to].kind!=='prefix').map((e,i)=>({id:'relation-'+i,From:all[e.from].id,To:all[e.to].id,Label:{text:e.kind+' · '+e.certainty},Kind:['candidate','unresolved-target'].includes(e.certainty)?'dashed':'plain'}));
 return {name:g.meta[3],nodes,edges:rendered,extensions:{containers}};
}
function draft(n,x,y){return {id:n.id,Label:{text:n.label},Position:{x:x+105,y:y+36},Size:{w:210,h:72},NodeType:['postgres','table'].includes(n.kind)?'database':n.kind==='kafka'?'kafka':'rounded',Color:({service:'blue',ui:'purple','ui-repository':'purple',kafka:'orange',postgres:'green',table:'green'})[n.kind]||'gray',Description:n.kind,DescriptionPlacement:'inside'};}
async function load(){
 const seq=++generation;message('Loading map…');const qs=new URLSearchParams(options());if(!librariesInitialized){qs.delete('libraries');qs.delete('candidates');}if(focus!==null)qs.set('focus',focus||'');
 const response=await api('/graph?'+qs),bytes=await response.arrayBuffer();if(seq!==generation)return;graph=dtMapFormat.decode(bytes);if(!librariesInitialized){$('map-libraries').checked=response.headers.get('x-dt-map-libraries')==='1';$('map-candidates').checked=response.headers.get('x-dt-map-candidates')==='1';librariesInitialized=true;$('map-libraries').dispatchEvent(new Event('input',{bubbles:true}));}if(focus===null)focus=decodeURIComponent(response.headers.get('x-dt-map-focus')||'');
 $('map-title').textContent=graph.meta[3];$('map-counts').textContent=`${graph.count} shown / ${graph.meta[4]} entities · ${graph.edgeCount} relations in this slice · ${graph.meta[6]} entities outside this view`;
 $('map-mode').textContent=focus?'Exact nodes and evidence in this bounded neighborhood. Prefix boundaries describe naming only.':'Inventory by service-name prefix. Expand a container to see services. No rolled-up dependency arrows.';
 if(!canvas){canvas=createCanvas({target:$('map-canvas'),mode:'read-only',ui:{fit:'readable',panels:false,hotkeys:{'view.fit.all':'f'},inheritHotkeys:false}});canvas.ctx.runtime.setFlag('containers',true);window.dtMapCanvas=canvas;canvas.ctx.bus.on('selection.changed',()=>{const ref=canvas.ctx.selection.selected();if(ref&&['node','container'].includes(ref.kind))inspect(ref.id).catch(message);});}
 canvas.load(documentFor(graph));canvas.fit();setTimeout(()=>{const view=canvas.ctx.contexts.view,current=view.get();if(current.scale<0.75){view.set({scale:0.75,x:-30,y:-20});canvas.ctx.bus.emit('view.changed',view.get());}},250);
 list(Array.from({length:graph.count},(_,i)=>graph.node(i)));message('');$('map-download').href=base+'/full';$('map-download').download='microservices.dtm';
 if(embed)dtInline.mount(document.querySelector('.map-shell'),{title:'Microservice map',summary:`${graph.meta[4]} entities · bounded evidence view`,open:true});postHeight();
 parent.postMessage({type:'dt:map-ready',map:id},'*');
}
async function search(){const seq=++searchSequence,q=$('map-search').value.trim();if(!q){list(Array.from({length:graph?.count||0},(_,i)=>graph.node(i)));return;}const r=await(await api('/search?'+new URLSearchParams({q,...options()}))).json();if(seq!==searchSequence)return;list(r.text?r.text.split('\n').map(line=>{const [id,kind,label]=line.split('\t');return {id,kind,label,scope:''};}):[]);message(r.truncated?`${r.total} matches; showing the first 30. Narrow the search.`:'');}
window.addEventListener('message',e=>{
 if(e.source!==parent||e.data?.map!==id)return;
 if(e.data.type==='dt:map-host'){host=e.data.run===true;if($('map-call-run'))$('map-call-run').disabled=!host;return;}
 if(e.data.type!=='dt:map-result'||e.data.request!==activeRequest)return;activeRequest=null;
 if(!$('map-tool-output'))return;$('map-call-run').disabled=!host;$('map-call-status').textContent=e.data.error?'Tool failed. Review the result.':'Completed.';$('map-tool-output').hidden=false;$('map-tool-status').textContent=e.data.error||e.data.tool+' completed'+(e.data.visualizationError?' · Visualization unavailable: '+e.data.visualizationError:'');$('map-tool-json').textContent=JSON.stringify(e.data.result||{error:e.data.error},null,2);$('map-tool-raw').open=!!e.data.error||!e.data.view;
 const frame=$('map-tool-view');frame.hidden=!e.data.view;if(e.data.view)frame.src=e.data.view;
 const editor=$('map-edit-adjustments');editor.replaceChildren();for(const a of e.data.result?.adjustments||[]){const button=document.createElement('button');button.textContent='Edit '+a.title;button.onclick=()=>{if(!a.nodes){prepare('map_adjustments',{id:a.id});runTool('map_adjustments',{id:a.id});return;}prepare('map_adjust',{id:a.id,title:a.title,evidence:a.evidence,expected_revision:a.revision,nodes:a.nodes.filter(n=>n.source==='manual:'+a.id).map(({id,kind,label,scope,repo,detail})=>({id,kind,label,scope,repo,detail})),edges:a.edges.map(e=>({from:e.from,to:e.to,relation:e.kind,evidence:e.evidence,suppress:e.certainty==='suppressed'}))});};editor.append(button);}
 if(e.data.tool==='map_adjust'&&!e.data.error)load().catch(message);
});
$('map-search').oninput=()=>{clearTimeout(search.timer);search.timer=setTimeout(()=>search().catch(message),200);};
$('map-overview').onclick=()=>{focus='';$('map-search').value='';load().catch(message);};$('map-libraries').onchange=$('map-candidates').onchange=()=>load().catch(message);$('map-fit').onclick=()=>canvas?.fit();
let last=0;function postHeight(){if(!embed||parent===window)return;const height=Math.ceil(document.body.getBoundingClientRect().height);if(height!==last){last=height;parent.postMessage({type:'iframe:height',height},'*');}}
new ResizeObserver(postHeight).observe(document.body);for(const delay of [500,1500,3000])setTimeout(postHeight,delay);window.addEventListener('pagehide',()=>canvas?.destroy());load().catch(message);
